package com.ruoyi.paismart.application.intelligence;

import com.ruoyi.paismart.configuration.PaismartEnabled;
import com.ruoyi.paismart.infrastructure.PaismartKafkaRuntime;
import com.ruoyi.paismart.infrastructure.storage.DocumentObjectStore;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import java.nio.file.*;
import java.util.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.core.env.Environment;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

/** 请求时按批准开关做非付费只读探测；路径、运行循环和配置状态明确其证据范围。 */
@Service
@PaismartEnabled
public class DependencyStatusService {
    private final Environment env;private final StringRedisTemplate redis;private final ObjectProvider<PaismartKafkaRuntime> kafka;private final DocumentObjectStore objects;private final IntelligenceSettings settings;private final ControlledHttp http;
    public DependencyStatusService(Environment env,StringRedisTemplate redis,ObjectProvider<PaismartKafkaRuntime> kafka,DocumentObjectStore objects,IntelligenceSettings settings,ControlledHttp http){this.env=env;this.redis=redis;this.kafka=kafka;this.objects=objects;this.settings=settings;this.http=http;}
    public List<Map<String,Object>> components(){return List.of(redis(),elasticsearch(),minio(),kafka(),worker(),liteparse(),ocr(),payment());}
    private Map<String,Object> state(String name,String state,boolean tested,String scope,String reason){return Map.of("name",name,"state",state,"tested",tested,"scope",scope,"reason",reason);}
    private Map<String,Object> redis(){if(redis.getConnectionFactory()==null)return state("Redis","NOT_CONFIGURED",false,"SHARED_REDIS_PING","共享Redis连接尚未配置");try(var connection=redis.getConnectionFactory().getConnection()){String pong=connection.ping();return state("Redis","PONG".equalsIgnoreCase(pong)?"READY":"UNAVAILABLE",true,"SHARED_REDIS_PING","PONG".equalsIgnoreCase(pong)?"共享Redis已返回PING响应；未测试缓存写入":"共享Redis未返回有效PING响应");}catch(RuntimeException unavailable){return state("Redis","UNAVAILABLE",true,"SHARED_REDIS_PING","共享Redis只读探测失败");}}
    private Map<String,Object> elasticsearch(){if(!settings.enabled("external-calls-enabled"))return state("Elasticsearch","DISABLED",false,"ES_CLUSTER_READ","外部只读请求未启用");String endpoint=settings.text("elasticsearch.endpoint","");if(endpoint.isBlank()||settings.hosts().isEmpty())return state("Elasticsearch","NOT_CONFIGURED",false,"ES_CLUSTER_READ","ES地址或批准主机白名单缺失");try{String ref=settings.text("elasticsearch.secret-ref","");String credential=ref.isBlank()?null:"ApiKey "+settings.secret(ref);Map<String,Object> response=http.json("GET",endpoint.replaceAll("/+$","")+"/_cluster/health",credential,null,10);String color=Values.text(response.get("status"));boolean ready=Set.of("green","yellow").contains(color)&&!Boolean.TRUE.equals(response.get("timed_out"));return state("Elasticsearch",ready?"READY":"UNAVAILABLE",true,"ES_CLUSTER_READ",ready?"集群健康只读请求成功；未验证业务索引、向量或写入":"集群状态为red、超时或响应缺失健康字段");}catch(RuntimeException unavailable){return state("Elasticsearch","UNAVAILABLE",true,"ES_CLUSTER_READ","ES白名单、凭证或只读请求未通过");}}
    private Map<String,Object> minio(){try{Map<String,Object> probe=objects.probe();Map<String,Object> result=new LinkedHashMap<>(probe);result.put("name","MinIO");return result;}catch(RuntimeException unavailable){return state("MinIO","UNAVAILABLE",true,"CONFIGURED_BUCKET_HEAD","对象存储只读探测失败");}}
    private Map<String,Object> kafka(){if(!env.getProperty("paismart.jobs.kafka-enabled",Boolean.class,false))return state("Kafka消费","DISABLED",false,"LOCAL_CONSUMER_LOOP","Kafka消费未启用");if(env.getProperty("paismart.jobs.bootstrap-servers","").isBlank())return state("Kafka消费","NOT_CONFIGURED",false,"LOCAL_CONSUMER_LOOP","Kafka连接配置缺失");PaismartKafkaRuntime runtime=kafka.getIfAvailable();boolean running=runtime!=null&&runtime.isRunning();return state("Kafka消费",running?"READY":"UNAVAILABLE",true,"LOCAL_CONSUMER_LOOP",running?"中心消费循环正在运行；未证明所有broker、topic及ACL健康":"中心消费循环未运行，待恢复配置或连接");}
    private Map<String,Object> worker(){if(!settings.enabled("parse.process-enabled"))return state("Tika解析Worker","DISABLED",false,"CLASSPATH_EXISTENCE","解析进程未启用");String cp=settings.text("parse.worker-classpath","");if(cp.isBlank())return state("Tika解析Worker","NOT_CONFIGURED",false,"CLASSPATH_EXISTENCE","解析Worker classpath缺失");boolean ready=Arrays.stream(cp.split(java.util.regex.Pattern.quote(java.io.File.pathSeparator),-1)).allMatch(this::classpathEntry);return state("Tika解析Worker",ready?"READY":"NOT_CONFIGURED",false,"CLASSPATH_EXISTENCE",ready?"已配置classpath路径存在；未启动进程或验证全部解析格式":"classpath含缺失、不可读或空路径");}
    private boolean classpathEntry(String entry){try{if(entry.isBlank())return false;if(entry.endsWith("*")){Path directory=Path.of(entry.substring(0,entry.length()-1));if(!directory.isAbsolute()||!Files.isDirectory(directory))return false;try(var files=Files.list(directory)){return files.anyMatch(file->Files.isRegularFile(file)&&file.toString().endsWith(".jar"));}}Path path=Path.of(entry);return path.isAbsolute()&&Files.exists(path)&&Files.isReadable(path);}catch(Exception invalid){return false;}}
    private Map<String,Object> liteparse(){if(!settings.enabled("parse.process-enabled")||!"liteparse".equals(settings.text("parse.pdf-engine","liteparse")))return state("LiteParse","DISABLED",false,"EXECUTABLE_EXISTENCE","LiteParse进程未启用或不是当前PDF引擎");String command=settings.text("parse.liteparse-command","");boolean exists=false;try{Path path=Path.of(command);exists=path.isAbsolute()&&Files.isRegularFile(path)&&Files.isReadable(path);}catch(RuntimeException invalid){}return state("LiteParse",exists?"READY":"NOT_CONFIGURED",false,"EXECUTABLE_EXISTENCE",exists?"已配置绝对可执行路径存在；未启动CLI或验证OCR语言包":"LiteParse绝对可执行路径未配置或不存在");}
    private Map<String,Object> ocr(){if(!settings.enabled("ocr.aliyun-enabled")||!settings.enabled("external-calls-enabled"))return state("云OCR","DISABLED",false,"CONFIGURATION_ONLY","云OCR或资料外发开关未启用");try{settings.modelSecret(settings.text("ocr.secret-ref","ai.paismart.aliyun.ocr"),"OCR","aliyun");return state("云OCR","CONFIGURED_NOT_TESTED",false,"CONFIGURATION_ONLY","托管用途可解析；未上传页图或产生OCR费用");}catch(RuntimeException missing){return state("云OCR","NOT_CONFIGURED",false,"CONFIGURATION_ONLY","云OCR托管用途未配置或不可用");}}
    private Map<String,Object> payment(){if(!env.getProperty("paismart.payment.enabled",Boolean.class,false))return state("支付","DISABLED",false,"CONFIGURATION_ONLY","支付未启用");boolean configured=List.of("merchant-id","app-id","serial","notify-url","private-key-alias","api-v3-alias").stream().allMatch(key->!env.getProperty("paismart.payment."+key,"").isBlank());return state("支付",configured?"CONFIGURED_NOT_TESTED":"NOT_CONFIGURED",false,"CONFIGURATION_ONLY",configured?"必要配置字段存在；未请求证书交换、预支付或真实交易":"必要支付配置字段缺失");}
}

